-- A `float8` after an `int4` is aligned to 8 as an `int8` is: 2 677 characters is a 2 712-byte
-- row, one more than `btree_float8_after_int4_at_limit` holds.
-- @setup
CREATE TABLE t (a int4, b float8, c text);
CREATE INDEX t_i ON t (a, b, c);
-- @test
-- @expect-error: a float8 aligned to 8
-- @expect-message
-- @profile-lock
INSERT INTO t VALUES (1, 1, '');
